package net.civeira.phylax.features.access.userpersonalapikey.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userpersonalapikey.domain.UserPersonalApiKey;
import net.civeira.phylax.features.access.userpersonalapikey.domain.event.UserPersonalApiKeyEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserPersonalApiKeyEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserPersonalApiKeyEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserPersonalApiKey entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
